/// `mitre_time`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::too_many_arguments,
    reason = "one parameter per input of the description"
)]
pub fn exact(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    s1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    s2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    s3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
    s4: i128,
    n5x: i128,
    n5y: i128,
    n5z: i128,
    d5: i128,
    s5: i128,
    n6x: i128,
    n6y: i128,
    n6z: i128,
    d6: i128,
    s6: i128,
    n7x: i128,
    n7y: i128,
    n7z: i128,
    d7: i128,
    s7: i128,
    n8x: i128,
    n8y: i128,
    n8z: i128,
    d8: i128,
    s8: i128,
) -> Option<Sign> {
    value(
        n1x, n1y, n1z, d1, s1, n2x, n2y, n2z, d2, s2, n3x, n3y, n3z, d3, s3, n4x, n4y, n4z, d4, s4,
        n5x, n5y, n5z, d5, s5, n6x, n6y, n6z, d6, s6, n7x, n7y, n7z, d7, s7, n8x, n8y, n8z, d8, s8,
    )
    .map(|v| v.signum())
}
